select json_build_object('products',(select count(*) from commerce.products),'skus',(select count(*) from commerce.skus),'stocked_skus',(select count(*) from commerce.inventory where on_hand=3 and reserved=0),'orders',(select count(*) from commerce.orders),'auth_users',(select count(*) from auth.users),'rls_tables',(select count(*) from pg_tables where schemaname='commerce' and rowsecurity),'tables',(select count(*) from pg_tables where schemaname='commerce'),'public_intake',(select public_intake from commerce.settings),'live_expiry',(select live_expiry_approved from commerce.settings),'app_login',(select rolcanlogin from pg_roles where rolname='dearelle_app'),'app_super',(select rolsuper from pg_roles where rolname='dearelle_app'),'app_bypass_rls',(select rolbypassrls from pg_roles where rolname='dearelle_app'),'anon_usage',has_schema_privilege('anon','commerce','USAGE'),'authenticated_usage',has_schema_privilege('authenticated','commerce','USAGE'),'can_change_prices',has_table_privilege('dearelle_app','commerce.skus','UPDATE'),'can_add_owner',has_table_privilege('dearelle_app','commerce.owner_accounts','INSERT'),'can_anonymize',has_function_privilege('dearelle_app','commerce.anonymize_closed_orders()','EXECUTE')) as security_summary;
